fn broadcast_arrays(a: Vec<i8>, b: Vec<i8>) -> (Vec<i8>, Vec<i8>) {
    let m = a.len();
    let n = b.len();
    // We assume inputs are non-empty and one of:
    //   1) m == n
    //   2) m == 1
    //   3) n == 1
    let out_len = m.max(n);

    if m == n {
        // Same length: just return them as‐is.
        (a, b)
    } else if m == 1 {
        // a is scalar: repeat its single value.
        let ai = a[0];
        (vec![ai; out_len], b)
    } else {
        // b is scalar: repeat its single value.
        let bi = b[0];
        (a, vec![bi; out_len])
    }
}

